package com.core.docintel.pipeline.builder;
import com.core.docintel.pipeline.events.*;
import java.util.*;
/** Versioned settings are separate from processing edges. Validation never resolves secrets. */
final class CapabilitySettings {
 static Map<String,Object> map(Object value){if(value==null)return Map.of();if(!(value instanceof Map<?,?> m))throw new IllegalArgumentException("Capability setting must be an object.");Map<String,Object> out=new LinkedHashMap<>();m.forEach((k,v)->{if(!(k instanceof String s))throw new IllegalArgumentException("Invalid setting key.");if(v==null)throw new IllegalArgumentException("Capability values cannot be null.");out.put(s,v);});return out;}
 static List<Map<String,Object>> objects(Object v){if(v==null)return List.of();if(!(v instanceof List<?> list)||list.size()>128)throw new IllegalArgumentException("Capability list must contain at most 128 items.");return list.stream().map(CapabilitySettings::map).toList();}
 static List<String> strings(Object v){if(v==null)return List.of();if(!(v instanceof List<?> list)||list.size()>256||list.stream().anyMatch(x->!(x instanceof String)))throw new IllegalArgumentException("Expected string list.");return list.stream().map(String.class::cast).toList();}
 static String text(Map<String,Object> m,String k,String fallback){Object v=m.get(k);if(v==null)return fallback;if(!(v instanceof String s)||s.length()>2000)throw new IllegalArgumentException("Invalid "+k);return s;}
 static void keys(Map<String,Object> m,Set<String> allowed){for(String k:m.keySet())if(!allowed.contains(k))throw new IllegalArgumentException("Unknown capability setting: "+k);}
 static void validate(PipelineDefinition d,boolean generation){
  Map<String,Object> c=map(d.capabilities());keys(c,Set.of("adapters","subscriptions","host","template"));
  Map<String,Map<String,Object>> adapters=new HashMap<>();
  for(Map<String,Object> a:objects(c.get("adapters"))){keys(a,Set.of("id","type","version","config"));String id=text(a,"id",""),type=text(a,"type","");if(!id.matches("[A-Za-z][A-Za-z0-9_-]{0,63}")||adapters.putIfAbsent(id,a)!=null)throw new IllegalArgumentException("Invalid or duplicate adapter ID.");if(!Set.of("ui","kafka","noop").contains(type)||!text(a,"version","1").equals("1"))throw new IllegalArgumentException("Unsupported adapter type/version.");Map<String,Object> config=map(a.get("config"));if(type.equals("kafka"))validateKafka(config);else if(!config.isEmpty())throw new IllegalArgumentException("This adapter has no configuration options.");}
  Map<String,Object> host=map(c.get("host"));keys(host,Set.of("type","port","openBrowser"));String hostType=text(host,"type","cli");if(!Set.of("cli","micronaut-web").contains(hostType))throw new IllegalArgumentException("Unsupported host.");Object port=host.get("port");if(port!=null&&(!(port instanceof Number n)||n.intValue()!=n.doubleValue()||n.intValue()<1||n.intValue()>65535))throw new IllegalArgumentException("Host port must be between 1 and 65535.");if(host.get("openBrowser")!=null&&!(host.get("openBrowser") instanceof Boolean))throw new IllegalArgumentException("openBrowser must be boolean.");
  if(generation&&hostType.equals("cli")&&adapters.values().stream().anyMatch(a->"ui".equals(a.get("type"))))throw new IllegalArgumentException("UIMessageAdapter requires the Micronaut Web App host for generated applications.");
  for(Map<String,Object> s:objects(c.get("subscriptions"))){keys(s,Set.of("adapterId","workflow","nodeIds","eventTypes","severities"));if(!adapters.containsKey(text(s,"adapterId","")))throw new IllegalArgumentException("Subscription references an unknown adapter.");PipelineType type;try{type=PipelineType.valueOf(text(s,"workflow",""));}catch(Exception e){throw new IllegalArgumentException("Subscription workflow must be ingestion or query.");}if(type==PipelineType.RAG_PROJECT||!d.hasWorkflow(type))throw new IllegalArgumentException("Subscription workflow is not present.");Set<String> ids=new HashSet<>();d.workflow(type).nodes().forEach(n->ids.add(n.id()));if(!ids.containsAll(strings(s.get("nodeIds"))))throw new IllegalArgumentException("Subscription references an unknown workflow node.");if(strings(s.get("eventTypes")).stream().anyMatch(x->!x.matches("[A-Z_]{1,64}")))throw new IllegalArgumentException("Invalid event type filter.");if(!Set.of("INFO","WARN","ERROR","DEBUG","TRACE").containsAll(strings(s.get("severities"))))throw new IllegalArgumentException("Invalid severity filter.");}
  Map<String,Object> template=map(c.get("template"));keys(template,Set.of("id","version","settings"));if(!text(template,"id","standard").matches("[A-Za-z0-9_-]{1,96}")||!text(template,"version","1").equals("1"))throw new IllegalArgumentException("Invalid template pin.");Map<String,Object> settings=map(template.get("settings"));if(settings.size()>32||settings.values().stream().anyMatch(x->!(x instanceof String||x instanceof Number||x instanceof Boolean)))throw new IllegalArgumentException("Template settings must be simple values.");
 }
 static void validateKafka(Map<String,Object> config){keys(config,Set.of("bootstrapServers","topic","clientId","securityProtocol","saslMechanism","username","password","truststoreLocation","truststorePassword"));if(text(config,"bootstrapServers","").isBlank()||!text(config,"topic","").matches("[A-Za-z0-9_.-]{1,249}"))throw new IllegalArgumentException("Kafka bootstrapServers and a valid topic are required.");for(String key:List.of("username","password","truststorePassword"))if(config.containsKey(key)&&!text(config,key,"").isEmpty()&&!text(config,key,"").matches("secret://env/[A-Za-z_][A-Za-z0-9_]*"))throw new IllegalArgumentException("Kafka credentials must use secret://env/NAME references.");if(!Set.of("PLAINTEXT","SSL","SASL_SSL","SASL_PLAINTEXT").contains(text(config,"securityProtocol","PLAINTEXT"))||!Set.of("PLAIN","SCRAM-SHA-256","SCRAM-SHA-512").contains(text(config,"saslMechanism","PLAIN")))throw new IllegalArgumentException("Unsupported Kafka security settings.");}
 static Map<String,Object> forWorkflow(Map<String,Object> config,PipelineType workflow){if(config==null)return null;Map<String,Object> c=new LinkedHashMap<>(config);c.put("subscriptions",objects(c.get("subscriptions")).stream().filter(s->workflow.name().equals(s.get("workflow"))).toList());return c;}
 static List<EventFilter> filters(Map<String,Object> c,String adapterId,PipelineType workflow){return objects(c.get("subscriptions")).stream().filter(s->adapterId.equals(s.get("adapterId"))&&workflow.name().equals(s.get("workflow"))).map(s->new EventFilter(new HashSet<>(strings(s.get("nodeIds"))),new HashSet<>(strings(s.get("eventTypes"))),new HashSet<>(strings(s.get("severities"))))).toList();}
 static List<EventFilter> uiFilters(Map<String,Object> c,PipelineType workflow){return objects(c.get("adapters")).stream().filter(a->"ui".equals(a.get("type"))).flatMap(a->filters(c,text(a,"id",""),workflow).stream()).toList();}
 static EventView view(Map<String,Object> c,PipelineType workflow){Map<String,Object> settings=c==null?Map.of():c;return new EventView(uiFilters(settings,workflow),objects(settings.get("adapters")).stream().noneMatch(a->"ui".equals(a.get("type"))));}
}

